{
  "PROP-6a4369e9-inv-013": {
    "property_id": "PROP-6a4369e9-inv-013",
    "audit_result": {
      "property_id": "PROP-6a4369e9-inv-013",
      "classification": "vulnerability",
      "code_path": "beacon-chain/rpc/prysm/v1alpha1/validator/proposer.go::broadcastAndReceiveDataColumns::L502-504",
      "proof_trace": "Locally-produced data columns bypass anti-equivocation cache. The broadcastAndReceiveDataColumns path saves columns via ReceiveDataColumns but never calls setSeenDataColumnIndex, while the gossip subscriber path (receiveDataColumnSidecar:L42) does update the cache. This violates the invariant that all imported columns must be tracked.",
      "attack_scenario": "Validator produces and broadcasts data columns which are saved to storage but not marked in the anti-equivocation cache, creating cache inconsistency that could allow duplicate column acceptance if re-submitted through different paths or enable equivocation detection bypass.",
      "checklist_id": "PROP-6a4369e9-inv-013"
    },
    "text": "Anti-equivocation cache must be updated for all imported data columns regardless of publishing.",
    "assertion": "forall col: imported(col) => anti_equivocation_cache.contains(col.key)",
    "covers": "SG-010",
    "severity": "HIGH",
    "type": "invariant"
  }
}

